insert into public.products
  (name, slug, description, category, price, compare_at_price, stock, image_url, featured, rating, review_count)
values
  ('Notebook URB Vortex 14 Core i7 16GB 512GB SSD', 'notebook-urb-vortex-14-core-i7-16gb-512gb-ssd-1', 'Ultrabook de 14 polegadas com processador Intel Core i7 de 13ª geração, 16GB de RAM DDR5 e SSD NVMe de 512GB. Tela IPS Full HD com 100% sRGB, teclado retroiluminado e 12h de autonomia.', 'Laptops', 5499.9, 6299.9, 24, '/images/laptop.jpg', true, 4.8, 214),
  ('Notebook Gamer URB Raptor 15 Ryzen 7 RTX 4060 32GB', 'notebook-gamer-urb-raptor-15-ryzen-7-rtx-4060-32gb-2', 'Máquina para jogos com Ryzen 7, GeForce RTX 4060 8GB, 32GB DDR5 e SSD de 1TB. Painel 15,6" 165Hz, sistema de dupla ventoinha e iluminação RGB por tecla.', 'Laptops', 8999.9, 9999.9, 11, '/images/laptop.jpg', true, 4.9, 168),
  ('Notebook URB Air 13 Snapdragon X 16GB 256GB', 'notebook-urb-air-13-snapdragon-x-16gb-256gb-3', 'Fino e silencioso, sem ventoinha. Chip ARM Snapdragon X, 16GB de RAM e 20h de bateria. Ideal para produtividade, reuniões e trabalho móvel.', 'Laptops', 4299.9, null, 30, '/images/laptop.jpg', false, 4.6, 97),
  ('Notebook URB Studio 16 Core Ultra 9 RTX 4070 64GB', 'notebook-urb-studio-16-core-ultra-9-rtx-4070-64gb-4', 'Estação de trabalho móvel para criação 3D, edição 8K e IA local. Core Ultra 9, RTX 4070, 64GB DDR5 e 2TB SSD. Tela OLED 16" com calibração de fábrica.', 'Laptops', 13999.9, 15499.9, 6, '/images/laptop.jpg', true, 4.9, 74),
  ('Notebook URB Essential 15 Core i5 8GB 256GB', 'notebook-urb-essential-15-core-i5-8gb-256gb-5', 'Opção econômica para estudos e tarefas do dia a dia. Core i5, 8GB de RAM, SSD de 256GB e tela antirreflexo de 15,6 polegadas.', 'Laptops', 2799.9, 3199.9, 48, '/images/laptop.jpg', false, 4.4, 331),
  ('Notebook URB Flip 14 2 em 1 Touch Core i7 16GB', 'notebook-urb-flip-14-2-em-1-touch-core-i7-16gb-6', 'Conversível com dobradiça 360°, tela sensível ao toque e caneta inclusa. Core i7, 16GB de RAM e SSD de 512GB para usar como notebook ou tablet.', 'Laptops', 6199.9, null, 17, '/images/laptop.jpg', false, 4.7, 88),
  ('Notebook URB Forge 17 Workstation Xeon 64GB RTX A3000', 'notebook-urb-forge-17-workstation-xeon-64gb-rtx-a3000-7', 'Certificado para engenharia e CAD. Tela 17" DCI-P3, RTX A3000 12GB, 64GB ECC e dois slots SSD. Refrigeração de vapor e portas Thunderbolt 4.', 'Laptops', 18990, 20990, 4, '/images/laptop.jpg', false, 4.8, 41),
  ('Smartphone URB Pulse 5G 256GB Preto Titânio', 'smartphone-urb-pulse-5g-256gb-preto-titanio-8', 'Tela AMOLED 6,7" 120Hz, chip octa-core 5G, 256GB de armazenamento e câmera tripla de 50MP com estabilização óptica. Bateria de 5000mAh com carga rápida de 67W.', 'Smartphones', 3299.9, 3799.9, 40, '/images/smartphone.jpg', true, 4.7, 512),
  ('Smartphone URB Pulse Pro 5G 512GB Câmera 200MP', 'smartphone-urb-pulse-pro-5g-512gb-camera-200mp-9', 'Topo de linha com sensor principal de 200MP, teleobjetiva periscópica 5x, tela LTPO 1-120Hz e resistência IP68. 12GB de RAM e 512GB de espaço.', 'Smartphones', 5999.9, 6799.9, 18, '/images/smartphone.jpg', true, 4.9, 287),
  ('Smartphone URB Lite 128GB Azul', 'smartphone-urb-lite-128gb-azul-10', 'Custo-benefício com tela de 6,6", bateria de 5000mAh que dura dois dias, câmera dupla de 50MP e leitor de digital lateral. 128GB expansíveis por microSD.', 'Smartphones', 1299.9, 1599.9, 75, '/images/smartphone.jpg', false, 4.4, 903),
  ('Smartphone URB Fold Dobrável 5G 512GB', 'smartphone-urb-fold-dobravel-5g-512gb-11', 'Tela interna flexível de 7,6" que abre como um tablet e tela externa de 6,2". Dobradiça testada para 400 mil ciclos, multitarefa com três apps e S-Pen compatível.', 'Smartphones', 10999.9, null, 7, '/images/smartphone.jpg', true, 4.6, 63),
  ('Smartphone URB Play 5G 256GB Gaming Edition', 'smartphone-urb-play-5g-256gb-gaming-edition-12', 'Feito para jogos: tela 165Hz, gatilhos capacitivos, sistema de resfriamento ativo e bateria de 6000mAh com carga de 100W. RAM de 16GB.', 'Smartphones', 3899.9, 4499.9, 22, '/images/smartphone.jpg', false, 4.7, 149),
  ('Smartphone URB Mini 5G 256GB Compacto', 'smartphone-urb-mini-5g-256gb-compacto-13', 'Para quem prefere aparelhos menores: 5,9" de tela, desempenho de topo, câmera de 50MP e bateria que encara o dia todo. Cabe em qualquer bolso.', 'Smartphones', 2999.9, null, 26, '/images/smartphone.jpg', false, 4.5, 118),
  ('Smartphone URB Go 64GB Entrada', 'smartphone-urb-go-64gb-entrada-14', 'Primeiro celular ou aparelho reserva. Tela de 6,5", Android limpo, câmera de 13MP e bateria de 5000mAh. Dual SIM e rádio FM.', 'Smartphones', 749.9, 899.9, 120, '/images/smartphone.jpg', false, 4.2, 640),
  ('Tablet URB Tab S 11 128GB Wi-Fi + Teclado', 'tablet-urb-tab-s-11-128gb-wi-fi-teclado-15', 'Tela LCD 11" 90Hz, 8GB de RAM, 128GB de espaço e som estéreo quádruplo. Acompanha capa-teclado magnética e suporte a caneta ativa.', 'Tablets', 2499.9, 2999.9, 33, '/images/tablet.jpg', true, 4.6, 176),
  ('Tablet URB Tab Ultra 14 OLED 256GB 5G', 'tablet-urb-tab-ultra-14-oled-256gb-5g-16', 'Painel OLED de 14,6" 120Hz para desenho e edição, 12GB de RAM, conexão 5G e bateria de 11200mAh. Caneta com 4096 níveis de pressão inclusa.', 'Tablets', 6499.9, null, 9, '/images/tablet.jpg', true, 4.8, 84),
  ('Tablet URB Tab A 10 64GB', 'tablet-urb-tab-a-10-64gb-17', 'Ideal para consumo de vídeo e leitura. Tela de 10,1", controle parental, modo infantil e bateria de longa duração. 64GB expansíveis.', 'Tablets', 1199.9, 1499.9, 54, '/images/tablet.jpg', false, 4.3, 298),
  ('Tablet URB Tab Kids 8 32GB com Capa Antichoque', 'tablet-urb-tab-kids-8-32gb-com-capa-antichoque-18', 'Projetado para crianças: capa emborrachada com alça, filtro de luz azul, conteúdo educativo e limite de tempo de tela. Garantia estendida contra quedas.', 'Tablets', 899.9, null, 61, '/images/tablet.jpg', false, 4.5, 205),
  ('Câmera Mirrorless URB M50 24MP + Lente 18-55mm', 'camera-mirrorless-urb-m50-24mp-lente-18-55mm-19', 'Sensor APS-C de 24,2MP, vídeo 4K30, estabilização no corpo e visor eletrônico OLED. Kit com lente 18-55mm f/3.5-5.6 e bateria extra.', 'Câmeras', 4599.9, 5299.9, 15, '/images/camera.jpg', true, 4.8, 132),
  ('Câmera Full Frame URB Pro R6 II Corpo', 'camera-full-frame-urb-pro-r6-ii-corpo-20', 'Sensor full frame de 24MP, 40 fps em rajada eletrônica, autofoco com detecção de olhos e vídeo 6K RAW. Corpo com vedação contra intempéries.', 'Câmeras', 14990, null, 5, '/images/camera.jpg', true, 4.9, 58),
  ('Câmera de Ação URB GoWave 5K À Prova d''Água', 'camera-de-acao-urb-gowave-5k-a-prova-d-agua-21', 'Grava em 5K60, estabilização eletrônica de última geração, à prova d''água até 10m sem caixa e tela frontal para vlogs. Kit com dois clipes e bateria.', 'Câmeras', 2199.9, 2599.9, 28, '/images/camera.jpg', false, 4.6, 241),
  ('Kit Câmera de Segurança URB Guard 3 Unidades 2K', 'kit-camera-de-seguranca-urb-guard-3-unidades-2k-22', 'Três câmeras Wi-Fi 2K com visão noturna colorida, detecção de pessoas por IA, sirene integrada e armazenamento local + nuvem. Instalação sem fios.', 'Câmeras', 1499.9, null, 37, '/images/camera.jpg', false, 4.4, 189),
  ('Fone URB Wave Pro ANC Bluetooth Over-Ear', 'fone-urb-wave-pro-anc-bluetooth-over-ear-23', 'Cancelamento de ruído adaptativo, 40h de bateria, drivers de 40mm e áudio espacial com rastreamento de cabeça. Dobrável, com estojo rígido.', 'Áudio', 1299.9, 1699.9, 44, '/images/headphones.jpg', true, 4.8, 376),
  ('Fone URB Buds 3 TWS com ANC', 'fone-urb-buds-3-tws-com-anc-24', 'Intra-auriculares sem fio com cancelamento de ruído, resistência IPX5, carga sem fio e 30h totais com o estojo. Modo transparência e baixa latência para jogos.', 'Áudio', 549.9, 749.9, 90, '/images/headphones.jpg', true, 4.6, 812),
  ('Caixa de Som URB Boom XL Bluetooth 80W', 'caixa-de-som-urb-boom-xl-bluetooth-80w-25', 'Som estéreo de 80W com graves reforçados, à prova d''água IP67, 24h de bateria e função power bank. Pareie duas unidades para som estéreo real.', 'Áudio', 999.9, 1249.9, 31, '/images/speaker.jpg', true, 4.7, 258),
  ('Caixa de Som Portátil URB Go Mini 20W', 'caixa-de-som-portatil-urb-go-mini-20w-26', 'Compacta e resistente, com alça de silicone, 12h de bateria, IP67 e microfone para chamadas. Cores vibrantes e som surpreendente para o tamanho.', 'Áudio', 299.9, null, 120, '/images/speaker.jpg', false, 4.5, 494),
  ('Soundbar URB Cinema 3.1 com Subwoofer Sem Fio', 'soundbar-urb-cinema-3-1-com-subwoofer-sem-fio-27', 'Barra de som 3.1 canais com Dolby Atmos, subwoofer sem fio de 8", HDMI eARC e modos de equalização. Transforma a TV em home theater.', 'Áudio', 1899.9, 2299.9, 19, '/images/speaker.jpg', false, 4.7, 143),
  ('Fone URB Studio Monitor Cabo P2/P10', 'fone-urb-studio-monitor-cabo-p2-p10-28', 'Fone de referência para produção musical, resposta plana de 5Hz a 40kHz, concha fechada e almofadas de veludo substituíveis. Cabo destacável com adaptadores.', 'Áudio', 799.9, null, 26, '/images/headphones.jpg', false, 4.8, 97),
  ('Fone URB Sport Open-Ear Condução Óssea', 'fone-urb-sport-open-ear-conducao-ossea-29', 'Não tampa o ouvido: ideal para correr no trânsito com segurança. Resistente a suor IP55, 8h de bateria e ajuste de titânio flexível.', 'Áudio', 649.9, 849.9, 52, '/images/headphones.jpg', false, 4.4, 168),
  ('Monitor URB View 27 QHD IPS 165Hz', 'monitor-urb-view-27-qhd-ips-165hz-30', '27 polegadas 2560x1440, painel IPS de 165Hz com 1ms, 99% sRGB e HDR400. Ajuste de altura, pivô e entradas DisplayPort + 2x HDMI.', 'Monitores', 1799.9, 2199.9, 34, '/images/monitor.jpg', true, 4.7, 221),
  ('Monitor Gamer URB Rush 24 Full HD 180Hz', 'monitor-gamer-urb-rush-24-full-hd-180hz-31', '24,5" Fast IPS 180Hz, sincronismo adaptativo, tempo de resposta de 0,5ms GtG e modo de mira. Base compacta que sobra espaço na mesa.', 'Monitores', 1099.9, 1399.9, 47, '/images/monitor.jpg', true, 4.6, 305),
  ('Monitor URB UltraWide 34 WQHD Curvo 144Hz', 'monitor-urb-ultrawide-34-wqhd-curvo-144hz-32', 'Curvatura 1500R, 3440x1440, 144Hz e cobertura DCI-P3 de 98%. KVM integrado e USB-C com 90W para trabalhar e jogar em uma tela só.', 'Monitores', 3499.9, null, 12, '/images/monitor.jpg', true, 4.8, 118),
  ('Monitor URB Creator 32 4K IPS Calibrado', 'monitor-urb-creator-32-4k-ips-calibrado-33', '32" UHD 4K com fábrica calibrada Delta-E < 2, 100% Adobe RGB, HDR600 e hub USB-C. Para fotografia, edição de vídeo e design.', 'Monitores', 4299.9, 4899.9, 8, '/images/monitor.jpg', false, 4.8, 76),
  ('Monitor URB Office 24 Full HD 75Hz', 'monitor-urb-office-24-full-hd-75hz-34', 'Econômico para escritório e estudo. IPS Full HD, 75Hz, luz azul reduzida sem cintilação e moldura fina. VESA e HDMI + VGA.', 'Monitores', 699.9, 899.9, 88, '/images/monitor.jpg', false, 4.4, 412),
  ('Console URB Station 5 1TB Edição Slim', 'console-urb-station-5-1tb-edicao-slim-35', 'Geração atual com SSD de 1TB, ray tracing, saída 4K120 e 8K. Acompanha controle sem fio com gatilhos adaptativos e retorno tátil.', 'Gaming', 3799.9, 4299.9, 20, '/images/console.jpg', true, 4.9, 640),
  ('Console Portátil URB Deck 512GB OLED', 'console-portatil-urb-deck-512gb-oled-36', 'PC de mão para jogos com tela OLED HDR de 7,4", 512GB, Wi-Fi 6E e até 12h de bateria. Roda sua biblioteca inteira na palma da mão.', 'Gaming', 4199.9, null, 14, '/images/console.jpg', true, 4.7, 203),
  ('Console URB Cube Series X 1TB', 'console-urb-cube-series-x-1tb-37', '12 teraflops, SSD NVMe de 1TB com expansão, Quick Resume e retrocompatibilidade com quatro gerações. Assinatura de jogos com 1 mês incluso.', 'Gaming', 3999.9, 4499.9, 16, '/images/console.jpg', true, 4.8, 289),
  ('Controle URB Elite Pro Sem Fio com Paddles', 'controle-urb-elite-pro-sem-fio-com-paddles-38', 'Botões traseiros programáveis, gatilhos com curso ajustável, sticks intercambiáveis e perfis salvos no controle. Estojo e base de recarga inclusos.', 'Gaming', 899.9, 1099.9, 38, '/images/console.jpg', false, 4.6, 154),
  ('Cadeira Gamer URB Throne Ergonômica Reclinável', 'cadeira-gamer-urb-throne-ergonomica-reclinavel-39', 'Encosto reclinável até 155°, apoio lombar e de pescoço em memória, braços 4D e cilindro classe 4. Suporta até 150kg.', 'Gaming', 1599.9, 1999.9, 22, '/images/keyboard.jpg', false, 4.5, 331),
  ('Volante URB Race GT Force Feedback + Pedais', 'volante-urb-race-gt-force-feedback-pedais-40', 'Force feedback por engrenagem, giro de 900°, câmbio borboleta e base de pedais com três pedais ajustáveis. Compatível com PC e consoles.', 'Gaming', 2299.9, null, 9, '/images/console.jpg', false, 4.7, 87),
  ('Smartwatch URB Watch 5 GPS Tela AMOLED', 'smartwatch-urb-watch-5-gps-tela-amoled-41', 'Tela AMOLED sempre ligada, GPS duplo, ECG, SpO2 e mais de 100 modos esportivos. Bateria de 7 dias e resistência 5ATM.', 'Wearables', 1499.9, 1899.9, 41, '/images/smartwatch.jpg', true, 4.7, 358),
  ('Smartwatch URB Watch Ultra Titânio 100m', 'smartwatch-urb-watch-ultra-titanio-100m-42', 'Caixa de titânio de 49mm, vidro de safira, GPS de precisão dupla frequência, mergulho até 100m e botão de ação configurável. Até 3 dias de uso intenso.', 'Wearables', 3999.9, null, 13, '/images/smartwatch.jpg', true, 4.8, 124),
  ('Pulseira Fitness URB Band 8', 'pulseira-fitness-urb-band-8-43', 'Monitor de sono, frequência cardíaca e estresse, 14 dias de bateria e tela AMOLED de 1,6". À prova d''água para nadar. Mais de 120 modos de treino.', 'Wearables', 299.9, 399.9, 110, '/images/smartwatch.jpg', false, 4.5, 967),
  ('Smartwatch URB Kids GPS com Chamada 4G', 'smartwatch-urb-kids-gps-com-chamada-4g-44', 'Relógio infantil com localização em tempo real, chamada de voz e vídeo 4G, botão SOS e cerca virtual. Lista de contatos controlada pelos pais.', 'Wearables', 599.9, null, 46, '/images/smartwatch.jpg', false, 4.3, 178),
  ('Teclado Mecânico URB Type K8 Sem Fio Hot-Swap', 'teclado-mecanico-urb-type-k8-sem-fio-hot-swap-45', 'Layout 75%, switches hot-swappable, conexão tripla (2,4GHz/Bluetooth/USB-C), estrutura de alumínio e keycaps PBT. Iluminação RGB por tecla.', 'Periféricos', 649.9, 849.9, 57, '/images/keyboard.jpg', true, 4.8, 402),
  ('Mouse URB Glide Pro Sem Fio 26K DPI 60g', 'mouse-urb-glide-pro-sem-fio-26k-dpi-60g-46', 'Sensor óptico de 26.000 DPI, 60g, switches ópticos de 90M de cliques e polling de 4000Hz com dongle. Até 90h de bateria.', 'Periféricos', 449.9, 599.9, 63, '/images/speaker.jpg', true, 4.7, 276),
  ('Kit Teclado + Mouse URB Office Combo Sem Fio', 'kit-teclado-mouse-urb-office-combo-sem-fio-47', 'Combo silencioso para trabalho: teclado com apoio de palma, mouse ambidestro e um único receptor USB. Pilhas com autonomia de 24 meses.', 'Periféricos', 229.9, null, 140, '/images/keyboard.jpg', false, 4.4, 588),
  ('Webcam URB Stream 4K com Tampa de Privacidade', 'webcam-urb-stream-4k-com-tampa-de-privacidade-48', 'Sensor 4K com HDR, foco automático, dois microfones com redução de ruído e correção de luz. Campo de visão ajustável 65°/78°/90°.', 'Periféricos', 549.9, 699.9, 35, '/images/camera.jpg', false, 4.6, 194),
  ('Microfone URB Cast USB Condensador com Braço', 'microfone-urb-cast-usb-condensador-com-braco-49', 'Cápsula cardioide de 25mm, monitoramento sem latência, botão de mudo tátil e ganho no corpo. Acompanha braço articulado e filtro pop.', 'Periféricos', 699.9, null, 28, '/images/speaker.jpg', false, 4.7, 133),
  ('Mousepad URB Deck XXL Speed 900x400mm', 'mousepad-urb-deck-xxl-speed-900x400mm-50', 'Superfície de tecido de baixa fricção, base emborrachada antiderrapante e bordas costuradas. Cobre teclado e mouse com folga.', 'Periféricos', 129.9, 179.9, 200, '/images/keyboard.jpg', false, 4.6, 741),
  ('Carregador URB GaN 100W 3 Portas USB-C', 'carregador-urb-gan-100w-3-portas-usb-c-51', 'Tecnologia GaN compacta que carrega notebook, tablet e celular ao mesmo tempo. Duas USB-C PD e uma USB-A, com proteção térmica.', 'Acessórios', 279.9, 349.9, 95, '/images/speaker.jpg', true, 4.7, 322),
  ('Power Bank URB Charge 20000mAh 30W com Visor', 'power-bank-urb-charge-20000mah-30w-com-visor-52', 'Bateria portátil de 20000mAh, saída de 30W PD, visor digital de porcentagem e recarga rápida do próprio power bank. Carrega o celular ~4 vezes.', 'Acessórios', 249.9, 329.9, 130, '/images/speaker.jpg', false, 4.6, 505),
  ('SSD Externo URB Rocket 1TB USB-C 1050MB/s', 'ssd-externo-urb-rocket-1tb-usb-c-1050mb-s-53', 'Do tamanho de um cartão de crédito, leitura de até 1050MB/s, corpo de alumínio com dissipação e resistência a quedas de 2m. Cabo USB-C e USB-A inclusos.', 'Acessórios', 599.9, 799.9, 42, '/images/console.jpg', true, 4.8, 217),
  ('Hub URB Link 9 em 1 USB-C HDMI 4K + Ethernet', 'hub-urb-link-9-em-1-usb-c-hdmi-4k-ethernet-54', 'Adaptador com HDMI 4K60, 3x USB-A, USB-C PD 100W, leitor SD/microSD e Ethernet gigabit. Ideal para notebooks finos e tablets.', 'Acessórios', 329.9, null, 68, '/images/keyboard.jpg', false, 4.5, 261),
  ('Suporte URB Ergo para Notebook em Alumínio', 'suporte-urb-ergo-para-notebook-em-aluminio-55', 'Eleva a tela à altura dos olhos, dobrável para levar na mochila, com ventilação aberta e apoios de silicone. Suporta notebooks de 10" a 17".', 'Acessórios', 159.9, 219.9, 115, '/images/keyboard.jpg', false, 4.6, 389)
